#pragma once

#include "HybridMarmotBridgeSpec.hpp"

#include <functional>
#include <memory>
#include <vector>

// Generated by cbindgen and copied here by `bun run build:native`.
#include "marmot_ffi.h"

namespace margelo::nitro::marmotnative {

/**
 * The heap context the mk-ffi host vtable drives: `rows` is the durable snapshot `load` serves
 * once (the `open` task clears it right after the `mk_bridge_open` that consumed it returns);
 * `commit` is the JS notification function. The vtable's `ctx` is a heap `std::shared_ptr`
 * pointing here — `release` deletes the box while this class holds the only other reference —
 * so the context outlives both destruction orders.
 */
struct HostContext {
  std::vector<uint8_t> rows;
  std::function<void(const std::shared_ptr<ArrayBuffer>&)> commit;
};

class HybridMarmotBridge final : public HybridMarmotBridgeSpec {
public:
  HybridMarmotBridge(MkBridge* handle, std::shared_ptr<HostContext> ctx) : HybridObject(TAG), _handle(handle), _ctx(std::move(ctx)) {}

  // mk_bridge_free never blocks: it enqueues shutdown and detaches the engine thread, which
  // still runs `release` exactly once.
  ~HybridMarmotBridge() override { mk_bridge_free(_handle); }

public:
  std::shared_ptr<Promise<std::shared_ptr<ArrayBuffer>>> open(const std::shared_ptr<ArrayBuffer>& config) override;
  std::shared_ptr<Promise<std::shared_ptr<ArrayBuffer>>> call(const std::shared_ptr<ArrayBuffer>& request) override;
  std::shared_ptr<Promise<std::shared_ptr<ArrayBuffer>>> drain() override;
  std::shared_ptr<Promise<void>> close() override;

private:
  MkBridge* _handle;
  std::shared_ptr<HostContext> _ctx;
};

} // namespace margelo::nitro::marmotnative
